head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.g_ACPT_NO = '';
scwin.gLastJob = "조회";
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.gSDate;
scwin.gEDate;
scwin.gSTimer;
scwin.gETimer;

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.dts_List_OnLoadError = function() {
    try {
        scwin.alert_error2(dts_List);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.dts_List_OnLoadError" });
    }
};

scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount <= 0) {

            dts_List.removeAll();
        }
        textbox_1.setValue("총 " + rowcount + "건");
        scwin.dispTimer(textbox_1); // 경과시간 표시

        btn_Search.setDisabled(true);
        btn_Search.setBackgroundImage("../img/btn_select.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.dts_List_OnLoadCompleted" });
    }
};

scwin.dts_List2_OnLoadError = function() {
    try {
        scwin.alert_error2(dts_List2);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.dts_List2_OnLoadError" });
    }
};

scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    try {
        if (rowcount <= 0) {

            dts_List2.removeAll();
        }
        textbox_2.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.dts_List2_OnLoadCompleted" });
    }
};

scwin.grd_List_OnDblClick = function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅  
        scwin.setContnId(dts_List, row);
        if (colid === 'DOC_TITLE') {

            fn_OpenDisclViewer_MGT(scwin.g_ACPT_NO, 'ULDMGT80235.gfm');
        } else if (colid !== 'DOC_TITLE' && colid !== 'ACPT_NO') {
            // 팝업 오픈
            scwin.popupSchdlExtrcOpen();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.grd_List_OnDblClick" });
    }
};

scwin.grd_List_OnClick = function(row, colid) {
    /*
    // 클릭된 값 변수에 셋팅  
    fn_setContnId(dts_List, row);

    if (colid != 'DOC_TITLE' && colid != 'ACPT_NO') {
    	//팝업 오픈
    	fn_PopupSchdlExtrcOpen();
    }
    */
};

scwin.grd_List2_OnClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅

    // fn_setContnId(dts_List2, row);

    // 팝업 오픈

    // fn_PopupSchdlExtrcOpen();

};

scwin.btn_Search_onclick = function(e) {
    try {
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.btn_Search_onclick" });
    }
};

scwin.btn_Excel_onclick = function(e) {
    try {
        let file_name = "일정추출";
        let today = $c.ut.cGetToday('yyyymmddhhmmss');
        let xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";

        grd_List.GridToOffice(file_name, xls_path, "8", 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.btn_Excel_onclick" });
    }
};

scwin.btn_Excel2_onclick = function(e) {
    try {
        let file_name = "일정추출";
        let today = $c.ut.cGetToday('yyyymmddhhmmss');
        let xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";

        grd_List2.GridToOffice(file_name, xls_path, "8", 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.btn_Excel2_onclick" });
    }
};

scwin.img_FromCal_onclick = function(e) {
    try {
        popUpCalendar2(edt_Date);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80235.img_FromCal_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
scwin.list = async function() {
    btn_Search.setDisabled(false);
    btn_Search.setBackgroundImage("../img/btn_select_d.gif");
    scwin.gSDate = new Date();
    scwin.gSTimer = scwin.gSDate.getTime();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/docprocslog.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_List_OnLoadCompleted(dts_List.getRowCount()); // 구 콜백 연결

};

scwin.list2 = async function() {
    const sbmOptions = {
        id : "sbm_dts_List2",
        action : "/docprocslog.do",
        ref : "",
        target : "dts_List2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_List2_OnLoadCompleted(dts_List2.getRowCount()); // 구 콜백 연결

};

///////// 5. 일반/업무 함수 영역 /////////
scwin.setCode = function() {
    edt_Date.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

};

scwin.validDateTodayCheck = function() {
    return true;
};

scwin.validCheck = function() {
    if (edt_Date.getValue().length < 8) {
        alert("[추출일자]를 올바르게 입력하세요.");

        edt_Date.focus();
        return false;
    }
    if (edt_StartTm.getValue().length < 4) {
        alert("[추출시간]을 올바르게 입력하세요.");

        edt_StartTm.focus();
        return false;
    }
    if (edt_EndTm.getValue().length < 4) {
        alert("[추출시간]을 올바르게 입력하세요.");

        edt_EndTm.focus();
        return false;
    }
    if (edt_StartTm.getValue() > edt_EndTm.getValue()) {
        alert("[시작시간]을 [종료시간] 이전으로 선택하세요.");

        edt_StartTm.focus();
        return false;
    }
    if (txb_ACPT_NO.getValue() !== "" && txb_ACPT_NO.getValue().length !== 14) {
        alert("[접수번호]를 올바르게 입력하세요.");

        txb_ACPT_NO.focus();
        return false;
    }
    return true;
};

scwin.search = function() {
    if (!scwin.validCheck()) {
        return;
    }
    scwin.list(); // 공시서식,상장서식,조건추출

    scwin.list2(); // 배치,화면

};

scwin.setContnId = function(obj, row) {

    scwin.g_ACPT_NO = obj.getCellData(eval(row), "ACPT_NO");
};

scwin.popupSchdlExtrcOpen = function() {
    const usrp = "/sysmonitor/ULDMGT80236.gfm";
    const winTitle = "일정추출 상세";

    frame.CreateDialogFrame("viewer_pop", usrp, winTitle, 0, -120, 1352, 1000, "window");
    // frame.Provider('/').OuterWindow.window.open(usrp,  "viewer_pop",
    //		"left=0,top=0,width=1750,height=965,resizable=yes,scrollbars=no,location=no,status=no");

};

scwin.dispTimer = function(textbox) {
    scwin.gEDate = new Date();
    scwin.gETimer = scwin.gEDate.getTime();
    const dispTimer = (scwin.gETimer - scwin.gSTimer) / 1000;
    const min = Math.round(dispTimer / 60, 2);
    const sec = Math.round(dispTimer % 60);

    // alert("처리시간 : " + min + " 분 " + sec + "초");

    textbox.value += " (처리시간 : " + min + " 분 " + sec + "초)";
};

scwin.alert_error2 = function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {

        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        let j;
        for (j = 0; j < errorCount; j++) {

            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) === '0') {
                // '0' 임의로 떨군 INFO 메시지

                alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                // 기존 에러 메시지

                alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};

scwin.gform_onload = function() {
    scwin.setCode();
    scwin.search();
};
